INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000052', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'The human body is made up of 206 bones. Bones are very important to the body. Bones keep some parts of the body safe. For example, the rib bones keep the heart and lungs safe. Bones help give the body its shape and work with muscles to help the body move.', NULL, NULL, 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000052', 'G3', 'RC', 52, 'What is the main idea of this passage?', '["The body has 206 bones.", "Bones are very important.", "Bones help give the body its shape.", "Rib bones keep the heart and lungs safe."]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000053', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Luke''s neighbor, Mrs. Shay, lives alone and writes books for children. Sometimes Mrs. Shay tells Luke about a story idea. She asks him what he thinks. If he likes the idea, she starts writing the story. Sometimes Luke asks Mrs. Shay for a favor. He asks her to listen while he practices reading out loud.', NULL, '00000000-0000-4000-8000-000000000053', 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8001-000000000053', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Every day. Luke brings Mrs. Shay her mail. Every week, he waters the flowers in Mrs. Shay''s three big flowerpots. One day, Luke needs to write a story for homework. He thinks and thinks, but he does not know what to write about. He asks Mrs. Shay. She says, Write about a nice boy who does chores for his neighbor."', NULL, '00000000-0000-4000-8000-000000000053', 2, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
