INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000058', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Tessa is nervous. Tonight she will play the plano in her first recital. She has been practicing for weeks. All of her family is going to see it. Her mother bought her a new shirt to wear. Tessa''s teacher showed her a special way to breathe that will help her relax before she goes out. Tessa will be sure to breathe in the special way tonight.', 'attend to go to an event
INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000058', 'G3', 'RC', 58, 'What does "recital" mean?', '["a way to calm down", "a piece of piano music", "a music or dance event", "a special way to breathe"]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
