INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000064', 'G3', 'RC', 64, 'Which sentence from the passage best explains why exercise is important for children?', '["\"These classes help get students ready for high school, college, and careers.\" (Paragraph 1)", "\"Being active helps young bodies and minds grow.\" (Paragraph 2)", "\"Our schools should have one hour of PE every day.\" (Paragraph 3)", "\"Teachers are sure to like that''\" (Paragraph 3)"]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
