INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000066', 'G3', 'RC', 66, 'Why does Emmet crumple the paper in paragraph 1?', '["He does not like writing", "He is angry with his sister.", "He does not want to clean up.", "He loses a game with his sister."]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000067', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Marnie needed a new lacket. Her old jacket was too small. Marnie went to the store with her dad. She tried on several jackets, but nothing fit quite right. Marnie saw a purple jacket with a butterfly on it. As she pulled it off the hanger, she hoped it would fit. With a big smile on her face, Marnie turned around to her dad. The jacket fit like a glove. Marnie was so excited to find a new jacket that she loved.', NULL, NULL, 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000067', 'G3', 'RC', 67, 'What is the meaning of the sentence, "The jacket fit like a glove"?', '["The jacket is the one Marnie loves most.", "The jacket is exactly the right size for Marnie.", "The jacket matches the color of Marnie''s gloves.", "The jacket fits Marnie in the same way as her old jacket."]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000068', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Paul finally finished his poster for his school project. He put it by the door so he would find it the next morning. On his way out the door the next day, Paul reached for his poster, but it was gone! Paul looked around and couldn''t find his poster.', NULL, NULL, 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000068', 'G3', 'RC', 68, 'What is the conflict in this story?', '["He found his poster.", "Paul lost his poster.", "Paul put his poster by the door.", "Paul took his poster to school."]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
