INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000088', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Paul finally finished his poster for his school project. He put it by the door so he would find it the next morning. On his way out the door the next day, Paul reached for his poster, but it was gone! Paul looked around and couldn''t find his poster.', NULL, NULL, 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
