INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000099', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Elephants live in Africa and Asia. The African elephant Is the biggest land animal in the world, It has very large ears. African elephants have two finger-like parts at the end of their trunks. These parts help the elephant grab things, like grass and sticks. The Aslan elephant is a little smaller than the African elephant. Its ears are smaller and rounder. It only has one finger-like part on its trunk.', NULL, NULL, 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
