INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000102', 'G3', 'RC', 102, 'Which meaning of break is used in the sentence?', '["to fracture", "to put an end to", "to smash into pieces", "to force through something"]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000103', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'One summer day, a fox saw a delicious-looking bunch of grapes on a vine hanging from a high tree branch. "Those juicy grapes are exactly what I need on this hot day." the fox sald. The fox jumped into the air to get the grapes but was unable to reach them. He tried again and again, but the grapes were simply too high. Finally, the fox gave up and walked away, saying, "I''ll bet those grapes are sour anyway."', NULL, '00000000-0000-4000-8000-000000000103', 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8001-000000000103', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Alexandra saw a kitten at the animal shelter and begged her father to buy it. Alexandra''s father apologized and explained that they already had a cat, and one pet was more than enough. Alexandra persisted and kept asking, and her father kept firmly saying no. Finally, Alexandra gave up and walked away, saying, "Having a kitten probably wouldn''t be much fun anyway.', NULL, '00000000-0000-4000-8000-000000000103', 2, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000103', 'G3', 'RC', 103, 'How are the fox in Passage 1 and Alexandra in Passage 2 alike?', '["When they see something they like, they work hard until they get it.", "When they want something nice. they are happy when they finally have it.", "When they do not like anything they see, they look for something better.", "When they cannot have something they want, they decide it is not any good."]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
