INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000104', 'G3', 'RC', 104, 'Based on the passage, choose two main ways today''s elevators differ from the first elevators.', '["Today''s elevators are faster.", "Today''s elevators are bigger.", "Today''s elevators are easier to build.", "Today''s elevators are powered by electricity. / Today''s elevators are for people instead of goods."]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
