INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000105', 'G3', 'RC', 105, 'How are scallops and clams different?', '["They eat different kinds of food.", "They have different types of bodies.", "They have different ways of feeding.", "They make their homes in different places."]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000106', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Slowly, slowly, Tayshon walked into his new school. He found room 102 at the end of the hall. He did not hear any sounds inside. Slowly, slowly, Tayshon opened the door. In silence, twenty faces turned to look at him. Their math books sat on the desks. Every book was open to the same page. One student dropped his book on the floor. Slam! It landed with a loud noise. Another girl was raising her hand. Instead, she put it down and she stared at Tayshon. It was a friendly stare. He stepped into the room.', NULL, NULL, 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000106', 'G3', 'RC', 106, 'Based on the details in the story, where does this story take place?', '["a public library", "a school bus", "a math class", "a school auditorium"]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000107', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'Ambrose stared at the row of locked boxes on the table. "One of them must have the key to the secret room." he thought. The first box was made of wood and had a picture of a horse on it. The second one was made of a silvery metal. Carvings of turtles covered the lid of the next wooden box. Finally, Ambrose looked at the last box. A picture of a door was carved into its wooden top. "This must be it," he thought.', NULL, NULL, 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000107', 'G3', 'RC', 107, 'Why does Ambrose think the last box holds the key?', '["It is a wooden box.", "It is silver in color.", "It has a lock on the front.", "It has a picture of a door on top."]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
