INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000119', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', 'People have lived near the Nile River for at least 20.000 years. About 9,000 years ago, Egyptian civilization rose up around the Nile. The Nile River was very important. Many people lived along the river. Every year the river flooded, leaving rich soil on its banks. People grew crops in the rich soil. They also used the Nile as source of drinking water. A plant called papyrus grew on the banks of the river. Ancient Egyptians used papyrus to make paper. The river provided many things necessary to the lives of the Ancient Egyptians', NULL, NULL, 1, 'MAP_RC_G2-4_PAST', 'PUBLISHED') ON CONFLICT (mpg_id) DO UPDATE SET mpg_body = EXCLUDED.mpg_body, mpg_glossary = EXCLUDED.mpg_glossary, mpg_pair_group_id = EXCLUDED.mpg_pair_group_id, mpg_grade = EXCLUDED.mpg_grade, updated_at = NOW();
INSERT INTO amb_acm_map_question (ent_id, mpg_id, mpq_grade, mpq_domain, mpq_external_no, mpq_question, mpq_choices, mpq_answer_index, mpq_difficulty, mpq_source, mpq_status) VALUES ('00000000-0000-0000-0000-000000000001', '00000000-0000-4000-8000-000000000119', 'G3', 'RC', 119, 'Which sentence from the passage best explains why Egyptian civilization rose up around the Nile River?', '["\"People have lived near the Nile River for at least 20,000 years.\"", "\"The Nile River was very important.\"", "\"A plant called papyrus grew on the banks of the river.\"", "\"The river provided many things necessary to the lives of the Ancient Egyptians.\""]'::jsonb, NULL, 'INTERMEDIATE', 'MAP_RC_G2-4_PAST', 'DRAFT') ON CONFLICT (ent_id, mpq_grade, mpq_external_no, mpq_source) DO UPDATE SET mpg_id = EXCLUDED.mpg_id, mpq_question = EXCLUDED.mpq_question, mpq_choices = EXCLUDED.mpq_choices, mpq_answer_index = EXCLUDED.mpq_answer_index, mpq_status = EXCLUDED.mpq_status, mpq_version = amb_acm_map_question.mpq_version + 1, updated_at = NOW();
INSERT INTO amb_acm_map_passage (mpg_id, ent_id, mpg_grade, mpg_domain, mpg_body, mpg_glossary, mpg_pair_group_id, mpg_ordinal, mpg_source, mpg_status) VALUES ('00000000-0000-4000-8000-000000000120', '00000000-0000-0000-0000-000000000001', 'G3', 'RC', '1. Lee inspected the wooden table she had just finished repairing in her antique store''s workshop. She saw that she had a visitor. It was Kyla McCoy, a girl who lived down the block. Lee knew that Kyla had taken a couple of woodworking classes in high school and that she was looking for a job. She didn''t know much else about Kyla, though. She needed to figure out if Kyla was competent enough to become her assistant.
